"""
task4_compare.py -- Task 4: fair comparison of the conventional system of Exercise 1 with the semantic system.

ONE protocol for every system
-----------------------------
* same channel drops: the 300 drops generated by the same call as in Exercise 1 (rng seed SEED+77);
* same test sentences (the 2000 test sentences) and the same metric code (metrics2.Scorer: BLEU, word accuracy,
  fastText similarity, exact match on lower-cased tokens);
* same optimiser: the exact MILP of sem_ra.py, applied to each system's rate matrix S~_{u,n};
* same unit and same minimum service: semantic units per second (suts/s), Smin = 2000 suts/s per user,
  an RB is usable only if its similarity is >= eps_th = 0.9.
  Conventional RB: S = (sentences/s of the AMC scheme) x (average similarity of that scheme at the RB's SNR);
  Semantic RB:    S = B I eps(K, gamma) / (K Lbar) with the best admissible K.

Experiments
-----------
 1. Pmax sweep 15..40 dBm: total semantic rate, % users served, cell-edge (5th percentile) rate, channel uses per
    sentence, fraction of sentences reproduced exactly, mean similarity.
 2. Bandwidth needed to serve all users: smallest number of RBs (180 kHz each, power per RB fixed to Pmax/16 at
    Pmax = 30 dBm, i.e. constant power spectral density) such that the MILP finds a solution with S_u >= Smin for all users.
 3. Robustness: SNR needed for similarity >= 0.9 (AWGN and Rayleigh + ZF), width of the quality transition, and
    knowledge-base mismatch (results of kb_mismatch.py).
 4. Complexity: parameters, floating-point operations and measured run time per sentence.
"""
import os, json, time
import numpy as np
from config import *
import resource_alloc as ra
import sem_ra
from rate_tables import get_systems, monotone

SWEEP_SYSTEMS = ["Semantic, adaptive K", "Semantic, fixed K=4", "Semantic, fixed K=8",
                 "Conventional, char Huffman + AMC", "Conventional, word Huffman + AMC",
                 "Conventional, char Huffman + meaning-aware MCS", "Conventional, word Huffman + meaning-aware MCS"]
N_MAX_RB = 48


# ------------------------------------------------------------------------------------ 1. Pmax sweep
def sweep(systems, a):
    keys = ("total_rate", "pct_served", "p5_rate", "uses_per_sentence", "exact_frac", "mean_eps")
    out = {s: {k: [] for k in keys} for s in SWEEP_SYSTEMS}
    for pdbm in PMAX_DBM_SWEEP:
        P = ra.dbm_to_w(pdbm)
        gam = 10 * np.log10(np.maximum(a * (P / N), 1e-30))
        for s in SWEEP_SYSTEMS:
            pr = systems[s](gam)
            ev = sem_ra.evaluate(sem_ra.milp_assign(pr["S"]), pr)
            for k in keys:
                out[s][k].append(ev[k])
        print(f"[4] Pmax {pdbm:5.1f} dBm | " + " | ".join(f"{s.split(',')[0][:4]}{s.split(',')[1].split()[0][:5]} {out[s]['total_rate'][-1]/1e3:6.1f}k/{out[s]['pct_served'][-1]:4.0f}%" for s in SWEEP_SYSTEMS[:5]), flush=True)
    return out


# ------------------------------------------------------------------------------------ 2. bandwidth to serve everyone
def drops_nrb(rng, D, n_rb):
    """Same generator as resource_alloc.generate_drops but with n_rb resource blocks (positions, path loss, shadowing, fading)."""
    r = np.sqrt(rng.uniform(MIN_DIST_M ** 2, CELL_RADIUS_M ** 2, size=(D, U)))
    pl_db = PL_A_DB + PL_B_DB * np.log10(r / 1000.0)
    sh_db = rng.normal(0.0, SHADOW_STD_DB, size=(D, U))
    ls = 10 ** (-(pl_db + sh_db) / 10.0)
    return ls[:, :, None] * rng.exponential(1.0, size=(D, U, n_rb)) / ra.noise_power_w()


def all_served(S):
    X = sem_ra.milp_assign_one(S)
    return bool(np.all((X * S).sum(1) >= S_MIN * (1 - 1e-9)))


def bandwidth_needed(systems, n_drops, pdbm=30.0):
    rng = np.random.default_rng(SEED + 99)
    a = drops_nrb(rng, n_drops, N_MAX_RB)
    p_rb = ra.dbm_to_w(pdbm) / N                         # constant power per RB (constant power spectral density)
    gam = 10 * np.log10(np.maximum(a * p_rb, 1e-30))
    out = {}
    for s in SWEEP_SYSTEMS:
        S = systems[s](gam)["S"]                         # (D,U,N_MAX)
        need = np.zeros(n_drops, int)
        for d in range(n_drops):
            if not all_served(S[d]):
                need[d] = N_MAX_RB + 1; continue           # not even N_MAX_RB are enough
            lo, hi = 1, N_MAX_RB                           # smallest n with all users served (monotone in n)
            while lo < hi:
                mid = (lo + hi) // 2
                if all_served(S[d][:, :mid]): hi = mid
                else: lo = mid + 1
            need[d] = lo
        ok = need <= N_MAX_RB
        out[s] = dict(mean_rb=float(need[ok].mean()), median_rb=float(np.median(need)),
                      p95_rb=float(np.percentile(need, 95)), frac_impossible=float(1 - ok.mean()),
                      mean_mhz=float(need[ok].mean() * B_RB / 1e6), need=need.tolist())
        print(f"[4] bandwidth {s:48s} mean {out[s]['mean_rb']:5.1f} RB  median {out[s]['median_rb']:4.1f}  p95 {out[s]['p95_rb']:5.1f}  impossible {100*out[s]['frac_impossible']:.0f}%", flush=True)
    return out


# ------------------------------------------------------------------------------------ 3. robustness
def snr_for(snr, y, level=EPS_TH):
    """Smallest SNR from which the (monotonised) curve stays >= level; inf if never."""
    y = monotone(y)
    idx = np.flatnonzero(y >= level)
    return float(snr[idx[0]]) if len(idx) else float("inf")


def robustness():
    sem = json.load(open(os.path.join(RES_DIR, "task2_sem_curves.json")))
    conv = json.load(open(os.path.join(RES_DIR, "task1_conv_sweeps.json")))["sweeps"]
    out = {"sem": {}, "conv": {}}
    for K, r in sem["K"].items():
        out["sem"][K] = {ch: snr_for(r[ch]["snr"], r[ch]["sim"]) for ch in ("awgn", "rayleigh", "rayleigh_word")}
        # transition width: SNR range in which similarity goes from 0.5 to 0.9
        s_awgn = np.array(r["awgn"]["snr"]); y = monotone(r["awgn"]["sim"])
        out["sem"][K]["width_50_90_awgn"] = snr_for(s_awgn, y, 0.9) - snr_for(s_awgn, y, 0.5)
    for src in ("char", "word"):
        for m in MCS_TABLE:
            n = m["name"]
            r = {ch: conv[src][ch][n] for ch in ("awgn", "rayleigh")}
            s = {ch: snr_for(r[ch]["snr"], r[ch]["sim"]) for ch in r}
            sa = np.array(r["awgn"]["snr"]); y = monotone(r["awgn"]["sim"])
            s["width_50_90_awgn"] = snr_for(sa, y, 0.9) - snr_for(sa, y, 0.5)
            out["conv"][f"{src}|{n}"] = s
    mm = os.path.join(RES_DIR, "task2_mismatch.json")
    if os.path.exists(mm):
        out["kb_mismatch"] = json.load(open(mm))
    return out


# ------------------------------------------------------------------------------------ 4. complexity
def complexity():
    import torch
    import link
    from corpus import load_corpus
    from tokens import Vocab
    from source_coding import CharHuffman
    from word_huffman import WordHuffman
    import semantic_model as sm
    import task2_semantic as t2
    tr, te = load_corpus(); vocab = Vocab(tr)
    sents = te[:200]
    out = {}
    # --- semantic: parameters, FLOPs (2 x matmul weights x tokens), measured time of transmitter + channel + receiver
    L_tx = float(np.mean([len(vocab.encode(s)) for s in sents]))
    for K in K_LIST:
        m = sm.load_codec(K, vocab, t2.ckpt(K)) if os.path.exists(t2.ckpt(K)) else sm.SemanticCodec(len(vocab), K)
        mat = sum(p.numel() for n_, p in m.named_parameters() if p.dim() == 2 and "emb" not in n_) + m.emb.weight.numel()  # tied output layer
        ids = sm.pad_batch(sm.encode_set(vocab, sents))
        with torch.no_grad():
            m(ids, 10.0)                                                  # warm-up
            t0 = time.perf_counter(); m(ids, 10.0); dt = (time.perf_counter() - t0) / len(sents)
        out[f"Semantic K={K}"] = dict(params=sm.count_params(m), mflops_per_sentence=2 * mat * L_tx / 1e6, ms_per_sentence=1e3 * dt)
    # --- conventional: Huffman + K=7 conv. code + 16-QAM 1/2, measured with the vectorised chain of Exercise 1
    mcs = MCS_TABLE[2]
    for src, h in (("char Huffman", CharHuffman(tr)), ("word Huffman", WordHuffman(vocab, tr))):
        t0 = time.perf_counter(); tx = link.TxFrames(h, sents, mcs); link.run(tx, 12.0, np.random.default_rng(0), want_text=True)
        dt = (time.perf_counter() - t0) / len(sents)
        steps = float(tx.T.mean())
        # Viterbi: per trellis step 64 states x 2 branches (add + compare) = 256 operations; + max-log demapper 2^m distances per symbol
        flops = steps * 256 + float(tx.n_sym.mean()) * (2 ** mcs["m"]) * 4
        out[f"Conventional, {src}"] = dict(params=len(h.codebook), mflops_per_sentence=flops / 1e6, ms_per_sentence=1e3 * dt)
    return out


def main():
    t0 = time.time()
    systems, sem = get_systems()
    rng = np.random.default_rng(SEED + 77)
    a = ra.generate_drops(rng, RA2_DROPS)
    res = dict(pmax_dbm=[float(x) for x in PMAX_DBM_SWEEP], n_drops=RA2_DROPS)
    res["sweep"] = sweep(systems, a)
    res["bandwidth"] = bandwidth_needed(systems, 20 if QUICK else 100)
    res["robustness"] = robustness()
    res["complexity"] = complexity()
    json.dump(res, open(os.path.join(RES_DIR, "task4_compare.json"), "w"))
    print(f"[task4] done in {time.time()-t0:.0f}s")


if __name__ == "__main__":
    main()
